dashboard.definition:
{
    "title": "Secure Networking Assurance",
    "description": "Connect protected application access, session continuity, path quality, distributed enforcement, and live threat context in one decision-ready score.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h,now,auto",
                "showAdvanced": true,
                "selections": [
                    {
                        "value": "-4h,now,auto",
                        "label": "4h"
                    },
                    {
                        "value": "-24h,now,auto",
                        "label": "24h"
                    },
                    {
                        "value": "-48h,now,auto",
                        "label": "48h"
                    },
                    {
                        "value": "-7d@d,now,auto",
                        "label": "7d"
                    },
                    {
                        "value": "-30d@d,now,auto",
                        "label": "30d"
                    }
                ],
                "token": "time_tok"
            },
            "title": "Time range",
            "type": "input.simpleTimePicker"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1c2738",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "Secure Networking Assurance",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/nav-icons/RobotAgent.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "markdown": "# Secure Networking Assurance\nConnect protected application access, session continuity, path quality, distributed enforcement, and live threat context in one decision\\-ready score\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Secure Networking Assurance Score**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Assurance  •  Agentic Ops"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Trends protected\\-application attainability, retainability, and path quality under time\\-aligned Cisco XDR incident pressure\\."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> sparklineValues | lastPoint()",
                "shouldAbbreviateMajorValue": false,
                "sparklineDisplay": "off",
                "trendDisplay": "absolute",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"SNAS\")",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)",
                "numberPrecision": 1,
                "unit": " / 100",
                "unitPosition": "after"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#649ef5",
                        "to": 0
                    },
                    {
                        "value": "#649ef5",
                        "from": 0
                    }
                ]
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.line",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#e44273",
                    "#3abdfa",
                    "#0d8e97",
                    "#e2a811",
                    "#9b5ff4",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "minmax",
                "lineWidth": 2,
                "markerDisplay": "outlined",
                "nullValueDisplay": "connect",
                "showYMajorGridLines": false,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | seriesByName(\"SNAS\")",
                "showYMinorGridLines": false,
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide"
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Secure%20Networking%20Assurance%20Score&target=XDR%20-%20Incident%20-%20Status%20and%20Severity%20Pressure%20Matrix,Secure%20Networking%20-%20ZTA%20ISE%20Auth%20Failure%20Rate%20by%20Network%20Device,Secure%20Networking%20-%20ThousandEyes%20HTTP%20Availability%20by%20Test"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
